import React, { FormEvent } from 'react';

import HikerSelectInput from '@apps/Hiking/@components/HikerSelectInput';
import { selectHikingScheduleItemInModal } from '@apps/Hiking/@components/ScheduleSelectModal';
import { mapHikerToUser, mapUserToHiker } from '@apps/Hiking/@mappers/hiking.mapper';
import { IHikingTransfer } from '@apps/Hiking/@types/hikingTransfers.types';
import { getInputDate } from '@helpers/dateHelper';
import PohButton, { ButtonVariant } from '@ui-kit/Button';
import IconsEnum from '@ui-kit/Icon/IconsEnum';
import PohInput, { InputTypes } from '@ui-kit/Input';
import PohCol from '@ui-kit/layout/Col';
import PohRow from '@ui-kit/layout/Row';
import { showModal } from '@ui-kit/Modal';

interface IHikingTransferFormProps {
  id_hiking: number;
  transfer: IHikingTransfer;
  onSave: (t: IHikingTransfer) => void;
  forMe?: boolean;
}

const HikingTransferForm = ({
  transfer,
  onSave,
  id_hiking,
  forMe = false,
}: IHikingTransferFormProps) => {
  const [modelData, setModelData] = React.useState<IHikingTransfer>(transfer);
  const onSubmit = (e: FormEvent) => {
    e.preventDefault();
    onSave(modelData);
  };

  function handleChange<k extends keyof IHikingTransfer>(fieldName: k) {
    return (value: IHikingTransfer[k]) => setModelData({ ...modelData, [fieldName]: value });
  }

  function handleChangeCar<k extends keyof IHikingTransfer['car']>(fieldName: k) {
    return (value: IHikingTransfer['car'][k]) =>
      setModelData({
        ...modelData,
        car: {
          ...modelData.car,
          [fieldName]: value,
        },
      });
  }

  function handleChangeDriver<k extends keyof IHikingTransfer['driver']>(fieldName: k) {
    return (value: IHikingTransfer['driver'][k]) =>
      setModelData({
        ...modelData,
        driver: {
          ...modelData.driver,
          [fieldName]: value,
        },
      });
  }

  function handleChangeStart<k extends keyof IHikingTransfer['start']>(fieldName: k) {
    return (value: IHikingTransfer['start'][k]) =>
      setModelData({
        ...modelData,
        start: {
          ...modelData.start,
          [fieldName]: value,
        },
      });
  }

  function handleChangeFinish<k extends keyof IHikingTransfer['finish']>(fieldName: k) {
    return (value: IHikingTransfer['finish'][k]) =>
      setModelData({
        ...modelData,
        finish: {
          ...modelData.finish,
          [fieldName]: value,
        },
      });
  }

  return (
    <form onSubmit={onSubmit} className="d-flex flex-column" style={{ gap: 12, minWidth: '60vw' }}>
      <PohRow>
        <PohCol sm={2}>План</PohCol>
        <PohCol sm={10} className="d-flex align-items-end">
          <PohInput
            placeholder="Нажмите чтобы выбрать пункт плана"
            defaultValue={modelData.schedule?.name ?? ''}
            readOnly
            required
            wrapperClassName="flex-grow-1"
            onClick={async () => {
              const selected = await selectHikingScheduleItemInModal(id_hiking);

              handleChange('schedule')(selected);
              setModelData((cur) => ({
                ...cur,
                schedule: selected,
                start: { ...cur.start, date: selected.start },
                finish: { ...cur.finish, date: selected.finish },
              }));
            }}
          />
          <PohButton icon={IconsEnum.close} onClick={() => handleChange('schedule')(null)} />
        </PohCol>
      </PohRow>

      <PohInput
        horizontal
        type={InputTypes.textarea}
        label="Комментарий"
        autoComplete="transfer-comment"
        name="transfer-comment"
        value={modelData.comment}
        onChange={handleChange('comment')}
        placeholder="Например: Поеду через бригадирский мост"
      />

      <h5>Машина</h5>
      <PohRow>
        <PohCol sm={2} />
        <PohCol sm={10}>
          <PohInput
            label="Название машины"
            value={modelData.car.name}
            onChange={handleChangeCar('name')}
            placeholder="Например: УАЗ Буханка"
            autoComplete="transfer-car-name"
            name="transfer-car-name"
            required
          />
        </PohCol>
      </PohRow>

      <PohRow>
        <PohCol sm={2} />
        <PohCol sm={3}>
          <PohInput
            label="Номер машины"
            value={modelData.car.number}
            onChange={handleChangeCar('number')}
            placeholder="Например: o273cc 58"
            autoComplete="transfer-car-number"
            name="transfer-car-number"
            required
          />
        </PohCol>
        <PohCol sm={3}>
          <PohInput
            label="Цвет машины"
            value={modelData.car.color}
            onChange={handleChangeCar('color')}
            placeholder="Серый как мышь"
            autoComplete="transfer-car-color"
            name="transfer-car-color"
            required
          />
        </PohCol>
        <PohCol sm={4}>
          <PohInput
            label="Фото машины"
            value={modelData.car.photo}
            onChange={handleChangeCar('photo')}
            placeholder="Ссылка на фото из интернета"
            type={InputTypes.url}
            required
            autoComplete="transfer-car-photo"
            name="transfer-car-photo"
          />
        </PohCol>
      </PohRow>
      <PohRow>
        <PohCol sm={2} />
        <PohCol sm={3}>
          <PohInput
            label="Вместимость (комфорт)"
            type={InputTypes.number}
            value={modelData.car.capacity ? modelData.car.capacity.toString() : ''}
            onChange={(v) => handleChangeCar('capacity')(v ? +v : 1)}
            min={1}
            max={50}
            step={1}
            autoComplete="transfer-car-capacity"
            name="transfer-car-capacity"
          />
        </PohCol>
        <PohCol sm={3}>
          <PohInput
            label="Вместимость (экстрим)"
            type={InputTypes.number}
            min={1}
            max={50}
            step={1}
            required
            autoComplete="transfer-car-capacity"
            name="transfer-car-capacity-max"
            value={modelData.car.capacity_max ? modelData.car.capacity_max.toString() : ''}
            onChange={(v) => handleChangeCar('capacity_max')(v ? +v : null)}
          />
        </PohCol>
      </PohRow>

      <h5>Водитель</h5>
      <PohInput
        horizontal
        label="Имя водителя"
        value={modelData.driver.name}
        onChange={handleChangeDriver('name')}
        required
        autoComplete="transfer-driver-name"
        name="transfer-driver-name"
      />

      <PohInput
        horizontal
        type={InputTypes.textarea}
        label="Контакты"
        value={modelData.driver.contacts}
        onChange={handleChangeDriver('contacts')}
        placeholder="Например, телефон чтобы связаться с водителем"
        required
        autoComplete="transfer-driver-contacts"
        name="transfer-driver-contacts"
      />
      <PohRow>
        <PohCol sm={2}>Если участник</PohCol>
        <PohCol sm={10} className="d-flex">
          <HikerSelectInput
            id_hiking={id_hiking}
            value={modelData.driver.user ? mapUserToHiker(modelData.driver.user) : null}
            onChange={(hiker) => handleChangeDriver('user')(mapHikerToUser(hiker))}
            wrapperClassName="flex-grow-1"
            disabled={forMe}
            message={
              forMe ? <small>Вы можете добавить только трансфер, где вы водитель</small> : ''
            }
          />
          <PohButton icon={IconsEnum.close} onClick={() => handleChangeDriver('user')(null)} />
        </PohCol>
      </PohRow>

      <h5>Старт</h5>
      <PohInput
        horizontal
        label="Время отправления"
        type={InputTypes.datetimeLocal}
        value={modelData.start.date ? getInputDate(modelData.start.date) : ''}
        onChange={(v) => handleChangeStart('date')(v ? new Date(v) : new Date())}
        required
      />
      <PohInput
        horizontal
        label="Точка отправления"
        value={modelData.start.description}
        onChange={handleChangeStart('description')}
        placeholder="Откуда выезжаем"
        required
        autoComplete="transfer-place-start"
        name="transfer-place-start"
      />

      <h5>Финиш</h5>
      <PohInput
        horizontal
        label="Время прибытия"
        type={InputTypes.datetimeLocal}
        value={modelData.start.date ? getInputDate(modelData.finish.date) : ''}
        onChange={(v) => handleChangeFinish('date')(v ? new Date(v) : new Date())}
        required
      />
      <PohInput
        horizontal
        label="Точка прибытия"
        value={modelData.finish.description}
        onChange={handleChangeFinish('description')}
        placeholder="Куда приезжаем"
        required
        autoComplete="transfer-place-finish"
        name="transfer-place-finish"
      />

      <PohRow>
        <PohCol sm={2} />
        <PohCol sm={10}>
          <PohButton type="submit" variant={ButtonVariant.Primary}>
            Сохранить
          </PohButton>
        </PohCol>
      </PohRow>
    </form>
  );
};

export const editHikingTransferInModal = (
  transfer: IHikingTransfer,
  id_hiking: number,
  forMe = false,
): Promise<IHikingTransfer> => {
  return new Promise((res) => {
    showModal({
      title: transfer.id > 0 ? 'Редактирование трансфера' : 'Добавление трансфера',
      children: (clos) => {
        return (
          <HikingTransferForm
            id_hiking={id_hiking}
            forMe={forMe}
            transfer={transfer}
            onSave={(up) => {
              res(up);
              clos();
            }}
          />
        );
      },
    });
  });
};
