import React from 'react';

import PersonPlus from '@pohodnik/icons/svg/People/PersonPlus';

import { selectHikerAsync } from '@components/HikerSelector/hikerSelectHelper';
import PageHeader from '@components/PageHeader';
import PageLoader from '@components/PageLoader';
import { AuthContext } from '@contexts/AuthContext';
import notificationHelper from '@helpers/notificationHelper';
import PohAlert, { AlertVariant } from '@ui-kit/Alert';
import PohAva from '@ui-kit/Ava';
import Breadcrumb from '@ui-kit/Breadcrumb';
import PohButton, { ButtonSize, ButtonVariant } from '@ui-kit/Button';
import Empty from '@ui-kit/Empty';
import IconsEnum from '@ui-kit/Icon/IconsEnum';
import PohCol from '@ui-kit/layout/Col';
import PohContainer from '@ui-kit/layout/Container';
import PohRow from '@ui-kit/layout/Row';
import PohList from '@ui-kit/List';

import { mapHikerToUser } from '../@mappers/hiking.mapper';
import { getHikingDataAsync } from '../@services/hiking.service';
import {
  addHikingTransfer,
  addHikingTransferMember,
  deleteHikingTransfer,
  deleteHikingTransferMember,
  editHikingTransfer,
  getHikingTransfers,
} from '../@services/hikingTransfers.service';
import { IHikingData } from '../@types/hiking.types';
import { IHikingTransfer } from '../@types/hikingTransfers.types';
import HikingTransferCard from './components/HikingTransferCard';
import { editHikingTransferInModal } from './components/HikingTransferForm';
import {
  getEmptyHikingTransferToFront,
  mapHikingTransferToAdd,
  mapHikingTransferToUpdate,
} from '../@mappers/hikingTransfers.mapper';
import { getHikingAccessGroupAsync } from '../@services/hikingRules.service';
import { HikingAccessGroup } from '../@types/hiking.rules';
import ScheduleItem from '../schedule/components/ScheduleItem';

interface IHikingTransfersProps {
  id_hiking: number;
}

const HikingTransfers: React.FC<IHikingTransfersProps> = ({ id_hiking }) => {
  const [isLoading, setIsLoading] = React.useState(true);
  const [err, setErr] = React.useState<Error>();

  const [data, setData] = React.useState<IHikingTransfer[]>([]);
  const [canEditOwn, setCanEditOwn] = React.useState(false);
  const [canEditSome, setCanEditSome] = React.useState(false);
  const [hikingData, setHikingData] = React.useState<IHikingData>();

  const authContext = React.useContext(AuthContext);

  React.useEffect(() => {
    const init = async () => {
      try {
        setIsLoading(true);

        const hd = await getHikingDataAsync(id_hiking);
        setHikingData(hd);

        const hdt = await getHikingTransfers(id_hiking);
        setData(hdt);

        const accessGroup = await getHikingAccessGroupAsync(id_hiking);
        setCanEditOwn(accessGroup !== HikingAccessGroup.Readonly);
        setCanEditSome(
          [HikingAccessGroup.Full, HikingAccessGroup.All, HikingAccessGroup.Boss].includes(
            accessGroup,
          ),
        );
      } catch (e) {
        setErr(e as Error);
      } finally {
        setIsLoading(false);
      }
    };

    init();
  }, [id_hiking]);

  if (isLoading) {
    return <PageLoader />;
  }

  if (err) {
    return <PohAlert variant={AlertVariant.Danger}>{err.message}</PohAlert>;
  }

  if (!hikingData || !authContext.user) {
    return <PohAlert variant={AlertVariant.Danger}>no hikingData</PohAlert>;
  }

  const transfersBySchedules = data.reduce<Record<number, IHikingTransfer[]>>((acc, val) => {
    const id = val.schedule?.id ?? 0;
    if (!acc[id]) acc[id] = [];
    acc[id].push(val);
    return acc;
  }, {});

  const renderOneTransfer = (transfer: IHikingTransfer) => {
    const isOwn =
      transfer.author.id === authContext.user?.id ||
      transfer.driver.user?.id === authContext.user?.id;

    return (
      <PohCol sm={6} md={4} lg={3} key={transfer.id}>
        <HikingTransferCard
          transfer={transfer}
          key={transfer.id}
          toolbar={
            canEditSome || (canEditOwn && isOwn) ? (
              <footer className="d-flex">
                <PohButton
                  icon={IconsEnum.trash}
                  onClick={async () => {
                    try {
                      const up = await deleteHikingTransfer({ id_hiking, id: transfer.id });
                      notificationHelper.success('Удалено');

                      up && setData((a) => a.filter((b) => b.id !== transfer.id));
                    } catch (error) {
                      notificationHelper.error((error as Error)?.message);
                    }
                  }}
                />

                <PohButton
                  icon={IconsEnum.edit}
                  onClick={async () => {
                    try {
                      const up = await editHikingTransferInModal(transfer, id_hiking);
                      await editHikingTransfer(mapHikingTransferToUpdate(id_hiking, up));
                      notificationHelper.success('Сохранено');
                      setData((a) => a.map((b) => (b.id == up.id ? up : b)));
                    } catch (error) {
                      notificationHelper.error((error as Error)?.message);
                    }
                  }}
                />

                <PohButton
                  icon
                  className="ms-auto"
                  title={`Добавить участника похода\nalt click чтобы добавить с комментарием`}
                  onClick={async (e) => {
                    try {
                      if (
                        transfer.members.length >=
                        (transfer.car.capacity_max ?? transfer.car.capacity ?? 50)
                      ) {
                        notificationHelper.warn(`Нет мест`);
                        return;
                      }
                      const hiker = await selectHikerAsync(id_hiking);
                      const comment =
                        e.altKey || e.metaKey ? (prompt('Комментарий', '') ?? '') : '';
                      const id = await addHikingTransferMember({
                        id_hiking,
                        id_hiking_transfer: transfer.id,
                        id_user: hiker.idUser,
                        comment,
                      });
                      notificationHelper.success('Сохранено');
                      setData((a) =>
                        a.map((b) =>
                          b.id == transfer.id
                            ? {
                                ...transfer,
                                members: [
                                  ...transfer.members,
                                  {
                                    id,
                                    comment,
                                    created_at: new Date(),
                                    id_author: hiker.idUser,
                                    user: mapHikerToUser(hiker),
                                  },
                                ],
                              }
                            : b,
                        ),
                      );
                    } catch (error) {
                      notificationHelper.error((error as Error)?.message);
                    }
                  }}
                >
                  <PersonPlus />
                </PohButton>
              </footer>
            ) : undefined
          }
        >
          <PohList
            flush
            data={transfer.members.map((u) => {
              return {
                key: u.id,
                className: 'p-1',
                children: (
                  <div className="d-flex align-items-center">
                    <PohAva
                      src={u.user.photo}
                      alt={u.user.name + ' ' + u.user.surname}
                      className="me-2"
                    />
                    <div>
                      <strong className="text-truncate text-nowrap me-2 d-block">
                        {u.user.name + ' ' + u.user.surname}
                      </strong>
                      {u.comment.length > 0 && (
                        <small>
                          <small className="text-muted">{u.comment}</small>
                        </small>
                      )}
                    </div>
                    {(canEditSome || (canEditOwn && isOwn)) && (
                      <PohButton
                        className="ms-auto"
                        icon={IconsEnum.trash}
                        onClick={async () => {
                          try {
                            await deleteHikingTransferMember({ id: u.id, id_hiking });
                            notificationHelper.success('Удалено');
                            setData((a) =>
                              a.map((b) =>
                                b.id == transfer.id
                                  ? {
                                      ...transfer,
                                      members: transfer.members.filter((v) => v.id !== u.id),
                                    }
                                  : b,
                              ),
                            );
                          } catch (error) {
                            notificationHelper.error((error as Error)?.message);
                          }
                        }}
                      />
                    )}
                  </div>
                ),
              };
            })}
          />
        </HikingTransferCard>
      </PohCol>
    );
  };

  return (
    <PohContainer>
      <Breadcrumb
        data={[
          { href: '/hiking', text: 'Походы' },
          { href: `/hiking/${id_hiking}`, text: hikingData.name },
          { href: `/hiking/${id_hiking}/transfers`, text: 'Трансферы', active: true },
        ]}
      />
      <PageHeader
        title={`Трансферы похода ${hikingData.name}`}
        subtitle="Здесь можно увидеть в какое время, на каком транспорте и даже с кем вы будете добираться до определенных точек"
      >
        {canEditOwn && (
          <PohButton
            onClick={async () => {
              try {
                const up = await editHikingTransferInModal(
                  getEmptyHikingTransferToFront(
                    { author: authContext.user! },
                    !canEditSome && authContext.user
                      ? {
                          driver: {
                            contacts: '',
                            name: authContext.user?.name,
                            user: authContext.user,
                          },
                        }
                      : {},
                  ),
                  id_hiking,
                  !canEditSome,
                );
                const id = await addHikingTransfer(mapHikingTransferToAdd(id_hiking, up));
                notificationHelper.success('Сохранено');
                setData((a) => [...a, { ...up, id }]);
              } catch (error) {
                notificationHelper.error((error as Error)?.message);
              }
            }}
            variant={ButtonVariant.Light}
            size={ButtonSize.Small}
          >
            Добавить
          </PohButton>
        )}
      </PageHeader>
      {!data.length && <Empty>Нет трансферов</Empty>}
      {Object.entries(transfersBySchedules).map(([scheduleIdOrZero, transfers]) => {
        return (
          <section key={scheduleIdOrZero}>
            <header className="d-flex align-items-center py-1 px-2 bg-light mb-1">
              <h4 className="m-0">{transfers[0].schedule?.name ?? 'Без привязки к плану'}</h4>
              {transfers[0].schedule && (
                <ScheduleItem
                  scheduleItem={transfers[0].schedule}
                  className="ms-auto border-top-0"
                />
              )}
            </header>
            <PohRow>{transfers.map(renderOneTransfer)}</PohRow>
          </section>
        );
      })}
    </PohContainer>
  );
};

export default HikingTransfers;
