import React from 'react';

import { IHikingTransfer } from '@apps/Hiking/@types/hikingTransfers.types';
import PohAva from '@ui-kit/Ava';
import PohCard from '@ui-kit/Card';
import PohCol from '@ui-kit/layout/Col';
import PohRow from '@ui-kit/layout/Row';

import transferImg from '../../../../img/nophoto.png';

interface IHikingTransferCardProps {
  transfer: IHikingTransfer;
  toolbar?: React.ReactNode;
  children?: React.ReactNode;
}

const HikingTransferCard = ({ transfer, toolbar, children }: IHikingTransferCardProps) => {
  return (
    <PohCard
      img={transfer.car.photo || transferImg}
      header={transfer.car.name}
      footer={toolbar}
      bodyClassName="p-0"
    >
      <div className="d-flex justify-content-between px-3 pb-1  bg-light mt-n2">
        <strong>{transfer.car.number}</strong>
        <strong>{transfer.car.color}</strong>
        <strong
          title={[
            'Число пассажиров',
            `Комфорт: ${transfer.car.capacity}`,
            `Максимум: ${transfer.car.capacity_max}`,
          ].join('\n')}
        >
          💺
          <sub className="text-success">{transfer.car.capacity}</sub>
          <sup className="text-danger">{transfer.car.capacity_max}</sup>
        </strong>
      </div>
      <div className="d-flex justify-content-between px-3 py-1  bg-light mt-n1 ">
        <div>
          <small className="text-muted d-block">
            Водитель: <strong className="text-warning">{transfer.driver.name}</strong>
          </small>

          <small className="d-block">
            <em>
              <small>{transfer.driver.contacts}</small>
            </em>
          </small>
        </div>
        {transfer.driver.user && (
          <div className="float-end">
            <PohAva src={transfer.driver.user.photo} alt={transfer.driver.user.name} />
          </div>
        )}
      </div>
      <div className="p-3 py-1 border-bottom bg-light">
        <em>{transfer.comment}</em>
      </div>
      <PohRow className="px-1 py-1 ">
        <PohCol xs={6} className="text-start">
          <small className="text-muted d-block">Старт</small>
          <small className="d-block">{transfer.start.date.toLocaleString()}</small>
          <small className="d-block border-bottom">
            <em>
              <small>{transfer.start.description}</small>
            </em>
          </small>
        </PohCol>
        <PohCol xs={6} className="text-end">
          <small className="text-muted d-block">Финиш</small>
          <small className="d-block">{transfer.finish.date.toLocaleString()}</small>
          <small className="d-block border-bottom">
            <em>
              <small>{transfer.finish.description}</small>
            </em>
          </small>
        </PohCol>
      </PohRow>
      {children}
    </PohCard>
  );
};

export default HikingTransferCard;
